-- reconciled: opening balance backed out from first txn, running balance ties
-- out to the sheet final balance of S$13,187.00).
-- Categories left blank -- your own sheet legend says they were not filled in yet;
-- tag them afterward in the Finance tab.
-- Just run this whole script once in the Supabase SQL editor -- no edits needed.

insert into finance_accounts (name, type, "openingBalance")
  select 'DBS Business Account', 'bank', 6072.42
  where not exists (select 1 from finance_accounts where name = 'DBS Business Account');

insert into finance_transactions (date, "accountId", type, category, description, amount, source)
